import type { NextRequest } from 'next/server'

/**
 * Extract the real client IP from a Next.js request.
 *
 * Priority:
 *  1. cf-connecting-ip  — Cloudflare's source-of-truth header (not spoofable past CF)
 *  2. x-forwarded-for[0] — first (leftmost) IP; this is the client IP as seen by the
 *     first proxy. On Railway + Cloudflare the chain is: client, CF-edge, Railway-edge.
 *     The leftmost value is the original client IP.
 *  3. x-real-ip         — set by some reverse proxies as a single-value shorthand
 *  4. 'anon'            — fallback when no headers are present (local dev)
 *
 * Note: x-forwarded-for is spoofable if the client sends their own header before
 * hitting Cloudflare. Prefer cf-connecting-ip on CF-proxied deployments.
 */
export function getClientIp(req: NextRequest): string {
  const cf = req.headers.get('cf-connecting-ip')
  if (cf) return cf.trim()

  const xff = req.headers.get('x-forwarded-for')
  if (xff) return xff.split(',')[0]!.trim()

  const xri = req.headers.get('x-real-ip')
  if (xri) return xri.trim()

  return 'anon'
}
