  // Step 4: Idempotency — atomic INSERT ON CONFLICT to prevent concurrent duplicate processing (M6)
  // If two concurrent deliveries of the same webhook-id arrive, exactly one INSERT wins.
  // The loser gets a unique-violation (23505) and returns 200 immediately without processing.
  const { data: claimed, error: claimError } = await supabase
    .from('webhook_events')
    .insert({
      source: 'dodo',
      event_id: eventId,
      payload: rawParsed as Json,
      processed_at: null,
      created_at: new Date().toISOString(),
    })
    .select('id')
    .maybeSingle()

  if (claimError) {
    if (claimError.code === '23505') {
      // Unique violation — another worker already claimed or is processing this event
      logger.info({ eventId }, 'dodo webhook: duplicate delivery, skipping')
      return NextResponse.json({ received: true, duplicate: true })
    }
    logger.error({ err: claimError, eventId }, 'dodo webhook: failed to claim event slot')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (!claimed) {
    logger.info({ eventId }, 'dodo webhook: duplicate delivery (no row returned), skipping')
    return NextResponse.json({ received: true, duplicate: true })
  }

  // Step 5: Parse typed event and process
  const eventResult = DodoWebhookEventSchema.safeParse({
    type: envelope.type,
    data: envelope.data,
  })

  if (!eventResult.success) {
    // Unknown event type — mark processed and return 200 so Dodo stops retrying
    logger.info({ type: envelope.type, eventId }, 'dodo webhook: unrecognized event type — ignoring')
    await supabase
      .from('webhook_events')
      .update({ processed_at: new Date().toISOString() })
      .eq('source', 'dodo')
      .eq('event_id', eventId)
    return NextResponse.json({ received: true, ignored: true })
  }

  const event = eventResult.data

  try {
    await processEvent(event, eventId, supabase)

    await supabase
      .from('webhook_events')
      .update({ processed_at: new Date().toISOString() })
      .eq('source', 'dodo')
      .eq('event_id', eventId)

    return NextResponse.json({ received: true })
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    logger.error({ err, eventId, type: event.type }, 'dodo webhook: processing failed')

    await supabase
      .from('webhook_events')
      .update({ error: errMsg })
      .eq('source', 'dodo')
      .eq('event_id', eventId)

    // Return 200 so Dodo doesn't retry — we've recorded the error for ops investigation
    return NextResponse.json({ received: true, error: errMsg })
  }
}

// ---------------------------------------------------------------------------
// Event processors
// ---------------------------------------------------------------------------

async function processEvent(
  event: DodoWebhookEvent,
  eventId: string,
  supabase: ReturnType<typeof createServiceRoleClient>
): Promise<void> {
  logger.info({ type: event.type, eventId }, 'dodo webhook: processing')

  switch (event.type) {
    case 'subscription.created':
    case 'subscription.updated':
      await handleSubscriptionUpsert(event.data, supabase)
      break
    case 'subscription.cancelled':
      await handleSubscriptionCancelled(event.data, supabase)
      break
    case 'subscription.trial_ended':
      await handleTrialEnded(event.data, supabase)
      break
    case 'invoice.created':
      await handleInvoiceCreated(event.data, supabase)
      break
    case 'invoice.paid':
      await handleInvoicePaid(event.data, supabase)
      break
    case 'invoice.payment_failed':
      await handleInvoicePaymentFailed(event.data, supabase)
      break
    case 'payment.succeeded':
      await handlePaymentSucceeded(event.data, supabase)
      break
    case 'payment.failed':
      await handlePaymentFailed(event.data, supabase)
      break
    case 'payment.refunded':
      await handlePaymentRefunded(event.data, supabase)
      break
    case 'customer.updated':
      await handleCustomerUpdated(event.data, supabase)
      break
  }
}

import { useState, useEffect } from 'react'

/**
 * Debounces a value by the given delay in ms.
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => {
      clearTimeout(timer)
    }
  }, [value, delay])

  return debouncedValue
}
