import { useEffect } from 'react'

/**
 * Scrolls the currently focused input into view when the virtual keyboard
 * opens. Uses the visualViewport API (supported in all modern mobile browsers).
 * Graceful no-op when visualViewport is not available.
 */
export function useKeyboardAware() {
  useEffect(() => {
    const vv = window.visualViewport
    if (!vv) return

    function handleResize() {
      const active = document.activeElement as HTMLElement | null
      if (!active) return
      const tag = active.tagName.toLowerCase()
      if (tag !== 'input' && tag !== 'textarea' && !active.isContentEditable) return
      // Keyboard is open — scroll active input into center of visible area
      active.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }

    vv.addEventListener('resize', handleResize)
    return () => vv.removeEventListener('resize', handleResize)
  }, [])
}

import { type NextRequest, NextResponse } from 'next/server'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { dodo } from '@/lib/dodo/client'

export const dynamic = 'force-dynamic'

/**
 * POST /api/billing/cancel
 * Schedules cancel_at_period_end = true via Dodo API.
 * Owner role required. Does NOT cancel immediately.
 *
 * M5: Does NOT write to local DB — the subscription.updated webhook from Dodo
 * is the source of truth. Writing optimistically before webhook confirmation
 * creates a divergence window if Dodo rejects the update asynchronously.
 */
export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'owner role required' }, { status: 403 })
  }

  const supabase = await createClient()
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('id, dodo_subscription_id, status')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!sub?.dodo_subscription_id) {
    return NextResponse.json({ error: 'no active subscription found' }, { status: 404 })
  }

  if (sub.status === 'canceled') {
    return NextResponse.json({ error: 'subscription is already cancelled' }, { status: 409 })
  }

  try {
    // Only call Dodo API — do NOT write cancel_at_period_end locally.
    // The subscription.updated webhook will flip the DB field once Dodo confirms.
    await (dodo.subscriptions as unknown as { update: (id: string, params: Record<string, unknown>) => Promise<unknown> }).update(sub.dodo_subscription_id, {
      cancel_at_period_end: true,
    })

    await logAuditAction(
      auth.user.authId,
      'billing.subscription.cancel_requested',
      { type: 'studio', id: auth.studioId },
      { dodoSubscriptionId: sub.dodo_subscription_id },
      auth.studioId,
    )

    // Return pending — UI should poll or rely on realtime subscription update from webhook
    return NextResponse.json({ ok: true, pending: true, message: 'Cancellation queued — will take effect at period end' })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'subscription cancel failed')
    return NextResponse.json({ error: 'failed to cancel subscription' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ id: string }> }

/**
 * POST /api/admin/studios/[id]/impersonate
 * Generates a 15-minute magic link for the studio owner.
 * Audit-logged. Single-use only (Supabase magic link is single-use by default).
 */
export async function POST(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    // Find the studio owner via studio_members + auth.users (via admin API)
    const ownerResult = await admin
      .from('studio_members')
      .select('user_id')
      .eq('studio_id', studioId)
      .eq('role', 'owner')
      .is('deactivated_at', null)
      .limit(1)
      .single()

    if (ownerResult.error || !ownerResult.data) {
      return Response.json({ error: 'Studio owner not found' }, { status: 404 })
    }

    // Get owner email from auth admin API
    const { data: ownerAuthUser, error: authUserError } = await admin.auth.admin.getUserById(ownerResult.data.user_id)
    if (authUserError || !ownerAuthUser?.user?.email) {
      return Response.json({ error: 'Owner email not found' }, { status: 404 })
    }

    const ownerEmail = ownerAuthUser.user.email

    // Generate magic link (single-use — Supabase default).
    // TTL: Supabase magic links expire after 1 hour by default (configurable in Supabase
    // Dashboard > Auth > Email > Magic link expiry). The expiresAt field below is an
    // advisory 15-minute window surfaced to the admin UI — the actual token lifetime
    // is controlled by Supabase Auth settings. To enforce a shorter server-side TTL,
    // set Email OTP Expiry to 900 seconds in the Supabase Auth config.
    // The Supabase auth admin API does not currently expose an expiresIn param for
    // generateLink — TTL is a project-level setting only.
    const { data: linkData, error: linkError } = await admin.auth.admin.generateLink({
      type: 'magiclink',
      email: ownerEmail,
    })

    if (linkError || !linkData) {
      throw linkError ?? new Error('Failed to generate magic link')
    }

    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString()

    await logAuditAction(
      user.id,
      'admin.impersonate',
      { type: 'studio', id: studioId },
      {
        target_email: ownerEmail,
        target_studio_id: studioId,
        expires_at: expiresAt,
      },
      null
    )

    return Response.json({
      signInUrl: linkData.properties?.action_link,
      expiresAt,
    })
  } catch (err) {
    logger.error({ err, studioId }, 'impersonate failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

