})

/**
 * DELETE /api/admin/studios/[id]/delete
 * Requires { confirm: "STUDIO_NAME" } in body.
 * Permanently deletes studio and all cascaded data (via FK CASCADE).
 */
export async function DELETE(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const body = bodySchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    const studioResult = await admin.from('studios').select('name').eq('id', studioId).single()
    if (!studioResult.data) return Response.json({ error: 'Studio not found' }, { status: 404 })

    if (body.data.confirm !== studioResult.data.name) {
      return Response.json(
        { error: `Confirmation does not match. Type "${studioResult.data.name}" exactly.` },
        { status: 422 }
      )
    }

    await logAuditAction(
      user.id,
      'admin.studio.delete',
      { type: 'studio', id: studioId },
      { studio_name: studioResult.data.name },
      null
    )

    const { error } = await admin.from('studios').delete().eq('id', studioId)
    if (error) throw error

    return Response.json({ deleted: true })
  } catch (err) {
    logger.error({ err, studioId }, 'studio delete failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

