'use client'

import type { ReactNode } from 'react'
import { Inbox, Loader2 } from 'lucide-react'
import { EmptyState } from './EmptyState'
import { PageError } from './PageError'
import { useLoadingTimeout } from '@/lib/hooks/use-loading-timeout'

interface DataStateProps<T> {
  data: T | null | undefined
  isLoading?: boolean
  isError?: boolean
  error?: Error | null
  isEmpty?: boolean
  children: (data: NonNullable<T>) => ReactNode
  loadingSlot?: ReactNode
  emptySlot?: ReactNode
  errorSlot?: ReactNode
}

function computeIsEmpty<T>(data: T | null | undefined, override?: boolean): boolean {
  if (override !== undefined) return override
  if (data == null) return true
  if (Array.isArray(data)) return data.length === 0
  return false
}

export function DataState<T>({
  data,
  isLoading = false,
  isError = false,
  error,
  isEmpty: isEmptyOverride,
  children,
  loadingSlot,
  emptySlot,
  errorSlot,
}: DataStateProps<T>) {
  const { showConnectionHint, showSlowHint } = useLoadingTimeout(isLoading)

  if (isError) {
    return (
      <>
        {errorSlot ?? (
          <PageError
            error={error ?? new Error('An error occurred')}
            reset={() => undefined}
            variant="inline"
          />
        )}
      </>
    )
  }

  if (isLoading) {
    const defaultSpinner = (
      <div
        className="flex flex-col items-center justify-center py-12"
        aria-busy="true"
        aria-label="Loading"
      >
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
        {showConnectionHint && !showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            Still loading — check your connection?
          </p>
        )}
        {showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            This is taking longer than expected.{' '}
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="underline underline-offset-2 hover:text-foreground transition-colors"
            >
              Retry
            </button>
          </p>
        )}
      </div>
    )

    return <>{loadingSlot ?? defaultSpinner}</>
  }

  const isEmpty = computeIsEmpty(data, isEmptyOverride)

  if (isEmpty) {
    return (
      <>
        {emptySlot ?? (
          <EmptyState
            icon={Inbox}
            title="Nothing here yet"
            size="md"
            variant="default"
          />
        )}
      </>
    )
  }

  return <>{children(data as NonNullable<T>)}</>
}

